(() => {
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let tab='portfolio',posts=[],current=null,photos=[],cover='',dirty=false,authMode='login',session={},busy=false,revision=0;
 const categories={portfolio:['주거','상업','사무','팝업','브랜딩','스타일링'],news:['공간 이야기','디자인 노트','네모 가이드']};
 const imageURL=key=>key?.startsWith('/media/')?key:key==='photo'?'/assets/hero.png':key==='office'?'/assets/office-3d.png':key==='popup'?'/assets/popup-3d.png':key==='a-home'?'/assets/home-3d-v2.png':key?'/assets/space-illustrations.png':'';
 async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body instanceof ArrayBuffer?{}:{'Content-Type':'application/json'}),...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||'처리하지 못했습니다.');return data;}
 function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3000);}
 function setDirty(value=true){dirty=value;if(value)revision++;$('#save-state').textContent=value?'저장되지 않은 변경 사항':current?.id?'저장됨':'새 글';}
 function abandon(){if(busy){toast('저장 또는 업로드가 끝날 때까지 기다려주세요.');return false;}return !dirty||confirm('저장하지 않은 변경 사항이 있습니다. 목록으로 돌아갈까요?');}
 async function refresh(){posts=(await api('/api/admin/posts')).posts;$('#portfolio-total').textContent=posts.filter(p=>p.type==='portfolio'&&p.status!=='archived').length;$('#news-total').textContent=posts.filter(p=>p.type==='news'&&p.status!=='archived').length;renderList();}
 function renderList(){
  const query=$('#search').value.trim().toLowerCase(),status=$('#status-filter').value,selected=posts.filter(p=>(tab==='archived'?p.status==='archived':p.type===tab&&p.status!=='archived')&&(status==='all'||p.status===status)&&p.title.toLowerCase().includes(query));
  $('#post-list').innerHTML=selected.map(p=>'<button class="post-card" data-post="'+esc(p.id)+'"><div class="cover">'+(p.payload.visual?'<img src="'+esc(imageURL(p.payload.visual))+'" alt="">':'<span class="cover-placeholder">NEMO.</span>')+'</div><div class="post-card-copy"><span class="badge '+(p.hasUnpublishedChanges?'changed':esc(p.status))+'">'+(p.status==='archived'?'휴지통':p.hasUnpublishedChanges?'게시 중 · 수정 중':p.status==='published'?'게시 중':'임시 저장')+'</span><h2>'+esc(p.title)+'</h2><span class="meta">'+esc(p.payload.category)+' · '+new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(p.updated)+'</span></div></button>').join('');
  $('#list-empty').hidden=selected.length!==0;
 }
 function switchTab(next){if(!abandon())return;tab=next;current=null;setDirty(false);$('#editor-view').hidden=true;$('#list-view').hidden=false;$('#new-post').hidden=tab==='archived';$('#status-filter').hidden=tab==='archived';$('#status-filter').value='all';$('#search').value='';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#list-title').textContent=tab==='portfolio'?'포트폴리오':tab==='news'?'뉴스룸':'휴지통';$('#list-description').textContent=tab==='portfolio'?'공간의 이야기를 차곡차곡 기록하세요.':tab==='news'?'네모의 소식과 생각을 전하세요.':'삭제한 글을 임시 글로 복원할 수 있습니다.';renderList();}
 function sectionsBody(sections){return sections.map(s=>(s[0]?'## '+s[0]+'\n':'')+s[1]).join('\n\n');}
 function parseSections(){const lines=$('#post-body').value.replace(/\r/g,'').split('\n');let title='',copy=[],sections=[];const push=()=>{if(title||copy.some(s=>s.trim()))sections.push([title,copy.join('\n').trim()]);};for(const line of lines){if(/^##\s+/.test(line)){push();title=line.replace(/^##\s+/,'').trim();copy=[];}else copy.push(line);}push();return sections;}
 function collect(){
  const p={id:current?.payload?.id,title:$('#post-title').value.trim(),category:$('#post-category').value,lead:$('#post-lead').value.trim(),visual:cover,sections:parseSections().map((s,i)=>{const previous=current?.payload?.sections?.[i]?.[2];return [...s,photos.includes(previous)?previous:photos.filter(k=>k!==cover)[i]||''];}),images:[...photos]};
  if(current.type==='portfolio')Object.assign(p,{style:$('#post-style').value,kind:$('#post-kind').value.trim(),intro:$('#post-intro').value.trim(),points:$('#post-points').value.split(',').map(s=>s.trim()).filter(Boolean),isActual:$('#post-actual').checked});return p;
 }
 function renderPhotos(){$('#photos').innerHTML=photos.map((key,i)=>'<div class="photo '+(cover===key?'cover-selected':'')+'"><img src="'+esc(imageURL(key))+'" alt="'+(i+1)+'번째 사진"><div><button class="choose-cover" type="button" data-cover="'+i+'">'+(cover===key?'대표 사진 ✓':'대표로 선택')+'</button><button type="button" data-remove="'+i+'" aria-label="'+(i+1)+'번째 사진 삭제">삭제</button></div></div>').join('');}
 function stateControls(){
  $('#post-state').textContent=current.status==='archived'?'휴지통':current.status==='published'?'게시 중'+(current.hasUnpublishedChanges?' · 수정 내용 임시 저장':''):'임시 저장';
  $('#unpublish').hidden=current.status!=='published';$('#archive').hidden=!current.id||current.status==='archived';$('#restore').hidden=current.status!=='archived';$('#publish').hidden=current.status==='archived';$('#save-draft').hidden=current.status==='archived';$('#publish').textContent=current.status==='published'?'수정 내용 게시':'게시하기';
 }
 function openPost(post){
  if(!abandon())return;current=post?structuredClone(post):{type:tab,status:'draft',payload:{category:categories[tab][0],style:'내추럴',isActual:true,sections:[],points:[]}};
  const p=current.payload;photos=[...new Set([p.visual,...(p.images||[]),...(p.sections||[]).map(s=>s[2])].filter(Boolean))];cover=p.visual||'';
  $('#post-title').value=p.title||'';$('#post-lead').value=p.lead||'';$('#post-body').value=sectionsBody(p.sections||[]);$('#post-category').innerHTML=categories[current.type].map(c=>'<option>'+esc(c)+'</option>').join('');$('#post-category').value=p.category||categories[current.type][0];$('#portfolio-fields').hidden=current.type!=='portfolio';$('#post-style').value=p.style||'내추럴';$('#post-kind').value=p.kind||'';$('#post-intro').value=p.intro||'';$('#post-points').value=(p.points||[]).join(', ');$('#post-actual').checked=p.isActual===true;$('#editor-error').textContent='';$('#list-view').hidden=true;$('#editor-view').hidden=false;$('#new-post').hidden=true;stateControls();renderPhotos();setDirty(false);$('#post-title').focus();
 }
 async function save(action='draft'){
  if(busy)return;busy=true;const savingRevision=revision;$('#editor-error').textContent='';$$('.editor-toolbar button').forEach(b=>b.disabled=true);
  try{const p=collect(),result=await api('/api/admin/posts'+(current.id?'/'+encodeURIComponent(current.id):''),{method:'POST',body:JSON.stringify({type:current.type,payload:p,action})});current={...current,...result,payload:p};setDirty(revision!==savingRevision);stateControls();await refresh();toast(action==='publish'?'홈페이지에 게시했습니다.':action==='archive'?'휴지통으로 이동했습니다.':action==='unpublish'?'비공개로 전환했습니다.':action==='restore'?'임시 글로 복원했습니다.':'임시 저장했습니다.');if(action==='archive'){busy=false;switchTab(tab);}return true;}catch(error){$('#editor-error').textContent=error.message;return false;}finally{busy=false;$$('.editor-toolbar button').forEach(b=>b.disabled=false);}
 }
 function authView(mode='login'){
  authMode=mode;$('#auth-screen').hidden=false;$('#workspace').hidden=true;$('#auth-title').textContent=mode==='setup'?'관리자 계정 만들기':mode==='recover'?'관리자 비밀번호 재설정':'관리자 로그인';$('#auth-description').textContent=mode==='setup'?'처음 한 번, 관리에 사용할 이메일과 비밀번호를 등록하세요.':mode==='recover'?'사이트 소유자 인증을 확인했습니다. 새로운 로그인 정보를 등록하세요.':'네모의 공간과 이야기를 관리하세요.';$('#confirm-label').hidden=mode==='login';$('#auth-confirm').required=mode!=='login';$('#auth-password').autocomplete=mode==='login'?'current-password':'new-password';$('#auth-submit').textContent=mode==='setup'?'관리자 계정 등록':mode==='recover'?'로그인 정보 재설정':'로그인';$('#recover').hidden=mode!=='login'||!session.canRecover;$('#owner-login').hidden=true;$('#auth-error').textContent='';$('#auth-password').value='';$('#auth-confirm').value='';
 }
 async function enterWorkspace(){await refresh();$('#auth-screen').hidden=true;$('#workspace').hidden=false;$('#account-email').textContent=session.email||$('#auth-email').value;if(!current)switchTab('portfolio');}
 $('#auth-form').addEventListener('submit',async event=>{event.preventDefault();$('#auth-error').textContent='';if(authMode!=='login'&&$('#auth-password').value!==$('#auth-confirm').value){$('#auth-error').textContent='비밀번호가 서로 다릅니다.';return;}$('#auth-submit').disabled=true;try{await api('/api/admin/'+authMode,{method:'POST',body:JSON.stringify({email:$('#auth-email').value,password:$('#auth-password').value})});session=await api('/api/admin/session');$('#auth-password').value='';$('#auth-confirm').value='';await enterWorkspace();}catch(error){$('#auth-error').textContent=error.message;}finally{$('#auth-submit').disabled=false;}});
 $('#recover').addEventListener('click',()=>authView('recover'));
 $('#logout').addEventListener('click',async()=>{if(!abandon())return;try{await api('/api/admin/logout',{method:'POST'});current=null;dirty=false;session=await api('/api/admin/session');authView();}catch(error){toast(error.message);}});
 $$('[data-tab]').forEach(button=>button.addEventListener('click',()=>switchTab(button.dataset.tab)));
 $('#search').addEventListener('input',renderList);$('#status-filter').addEventListener('change',renderList);$('#new-post').addEventListener('click',()=>openPost(null));
 $('#post-list').addEventListener('click',event=>{const button=event.target.closest('[data-post]');if(button)openPost(posts.find(p=>p.id===button.dataset.post));});
 $('#back-to-list').addEventListener('click',()=>switchTab(tab));$('#editor-form').addEventListener('input',()=>setDirty());$('#editor-form').addEventListener('submit',e=>e.preventDefault());
 $('#save-draft').addEventListener('click',()=>save('draft'));$('#publish').addEventListener('click',()=>save('publish'));$('#unpublish').addEventListener('click',()=>{if(confirm('이 글을 홈페이지에서 비공개로 전환할까요?'))save('unpublish');});$('#archive').addEventListener('click',()=>{if(confirm('휴지통으로 이동할까요? 나중에 복원할 수 있습니다.'))save('archive');});$('#restore').addEventListener('click',()=>save('restore'));
 $('#photos').addEventListener('click',event=>{const choose=event.target.closest('[data-cover]'),remove=event.target.closest('[data-remove]');if(choose){cover=photos[Number(choose.dataset.cover)];setDirty();renderPhotos();}if(remove){const key=photos.splice(Number(remove.dataset.remove),1)[0];if(cover===key)cover=photos[0]||'';setDirty();renderPhotos();}});
 $('#photo-upload').addEventListener('change',async event=>{
  if(busy){event.target.value='';return;}const files=[...event.target.files];if(photos.length+files.length>24){$('#editor-error').textContent='사진은 최대 24장까지 등록할 수 있습니다.';event.target.value='';return;}busy=true;event.target.disabled=true;$$('.editor-toolbar button').forEach(b=>b.disabled=true);
  const label=event.target.closest('label');label.classList.add('uploading');$('#editor-error').textContent='사진을 업로드하고 있습니다.';
  try{for(const file of files){if(file.size>12*1024*1024)throw new Error('사진은 한 장당 12MB 이하로 올려주세요.');const result=await api('/api/admin/media',{method:'POST',headers:{'Content-Type':file.type},body:await file.arrayBuffer()});photos.push(result.url);if(!cover)cover=result.url;renderPhotos();setDirty();}$('#editor-error').textContent='';}catch(error){$('#editor-error').textContent=error.message;}finally{event.target.value='';event.target.disabled=false;busy=false;$$('.editor-toolbar button').forEach(b=>b.disabled=false);label.classList.remove('uploading');}
 });
 $('#preview').addEventListener('click',()=>{const p=collect();$('#preview-content').innerHTML='<span class="eyebrow">'+esc(p.category)+'</span><h1>'+esc(p.title||'제목 없는 글')+'</h1><p class="lead">'+esc(p.lead)+'</p>'+(cover?'<img src="'+esc(imageURL(cover))+'" alt="">':'')+p.sections.map(s=>'<section>'+(s[0]?'<h2>'+esc(s[0])+'</h2>':'')+'<p>'+esc(s[1])+'</p>'+(s[2]?'<img src="'+esc(imageURL(s[2]))+'" alt="">':'')+'</section>').join('');$('#preview-dialog').showModal();});
 $('#close-preview').addEventListener('click',()=>$('#preview-dialog').close());$('#preview-dialog').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))e.currentTarget.close();});
 $('#preview').addEventListener('click',()=>{const p=collect(),used=new Set([p.visual,...p.sections.map(s=>s[2])]);for(const src of p.images.filter(src=>!used.has(src))){const image=document.createElement('img');image.src=imageURL(src);image.alt='';$('#preview-content').append(image);}});
 addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
 (async()=>{try{session=await api('/api/admin/session');if(session.authenticated)await enterWorkspace();else{authView(session.configured?'login':'setup');if(!session.configured&&!session.canSetup){$('#auth-error').textContent='최초 계정 등록은 사이트 소유자만 할 수 있습니다.';$('#auth-submit').disabled=true;$('#owner-login').hidden=false;}}}catch(error){$('#auth-error').textContent=error.message;}})();
})();
